from heapq import heappush, heappop
from math import inf

def shortest_path(graph, source, target):
    # Priority queue to store the (distance, node) pairs
    priority_queue = [(0, source)]
    # A dictionary to store the shortest distance to a node
    distance = {node: inf for node in graph}
    # A dictionary to store the previous node on the shortest path from source to node
    prev = {node: None for node in graph}
    # The distance to the source node is 0
    distance[source] = 0

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we reached the target node, we can construct the path
        if current_node == target:
            path = []
            while current_node:
                path.append(current_node)
                current_node = prev[current_node]
            return (current_distance, path[::-1])

        # If there is no negative weight cycle
        if current_distance > distance[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance_to_neighbor = current_distance + weight
            if distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                prev[neighbor] = current_node
                heappush(priority_queue, (distance_to_neighbor, neighbor))

    # If we exited the loop, the target is unreachable
    return (float("inf"), None)

