def shortest_path(graph, source, target):
    from heapq import heappush, heappop

    def dijkstra(graph, source, target):
        heap = [(0, source)]
        visited = set()
        path_dict = {source: []}
        while heap:
            (dist, node) = heappop(heap)
            if node in visited:
                continue
            visited.add(node)
            if node == target:
                return (dist, path_dict[node])
            for (neighbor, weight) in graph.get(node, []):
                if neighbor in visited:
                    continue
                new_path = path_dict[node] + [neighbor]
                total_dist = dist + weight
                if neighbor not in path_dict or total_dist < path_dict[neighbor][0]:
                    path_dict[neighbor] = (total_dist, new_path)
                heappush(heap, (total_dist, neighbor))
        return (float("inf"), None)

    return dijkstra(graph, source, target)
