def shortest_path(graph, source, target):
    import heapq
    from heapq import heappop, heappush
    from collections import deque

    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_dist, current_node = heappop(queue)

            if current_node == target:
                return current_dist

            for neighbor, weight in graph[current_node]:
                distance = current_dist + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(queue, (distance, neighbor))

        return float('inf')

    def bfs(graph, source, target):
        queue = deque([(source, [source])])
        visited = set([source])

        while queue:
            current_node, path = queue.popleft()

            for neighbor in graph[current_node]:
                if neighbor[0] not in visited:
                    visited.add(neighbor[0])
                    new_path = path + [neighbor[0]]
                    if neighbor[0] == target:
                        return new_path
                    queue.append((neighbor[0], new_path))

        return None

    if source == target:
        return (0, [source])

    if bfs(graph, source, target):
        return (len(bfs(graph, source, target)) - 1, bfs(graph, source, target))

    shortest_distance = dijkstra(graph, source)
    if shortest_distance == float('inf'):
        return (float('inf'), None)

    return (shortest_distance, [target])
