def dijkstra_shortest_path(graph, source, target):
    from heapq import heappush, heappop
    import math

    def min_heapify(heap, index):
        smallest = index
        left = 2 * index + 1
        right = 2 * index + 2

        if left < len(heap) and graph[heap[left][0]][1] < graph[heap[smallest]][1]:
            smallest = left

        if right < len(heap) and graph[heap[right][0]][1] < graph[heap[smallest]][1]:
            smallest = right

        if smallest != index:
            heap[smallest], heap[index] = heap[index], heap[smallest]
            min_heapify(heap, smallest)

    def dijkstra(graph, source):
        distances = {node: math.inf for node in graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            current_distance, current_node = heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for neighbour, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbour]:
                    distances[neighbour] = distance
                    heappush(priority_queue, (distance, neighbour))

        return distances

    distances = dijkstra(graph, source)
    if distances[target] == math.inf:
        return math.inf, None
    else:
        path = [target]
        current_node = target
        while current_node != source:
            for neighbour, weight in graph[current_node]:
                if distances[neighbour] == distances[current_node] - weight:
                    path.append(neighbour)
                    current_node = neighbour
                    break
        path.reverse()
        return distances[target], path

