def shortest_path(graph, source, target):
    # Disjoint Set Union (DSU) data structure or Union-Find structure to keep track of connected components
    class DSU:
        def __init__(self, data):
            # Initialize parent mapping and size for each element
            self.data = data
            self.parent = {idx: idx for idx in data}
            self.rank = {idx: 0 for idx in data}

        def find(self, idx):
            if idx != self.parent[idx]:
                self.parent[idx] = self.find(self.parent[idx])
            return self.parent[idx]

        def union(self, idx1, idx2):
            root1, root2 = self.find(idx1), self.find(idx2)
            if root1 != root2:
                if self.rank[root1] > self.rank[root2]:
                    self.parent[root2] = root1
                else:
                    self.parent[root1] = root2
                    if self.rank[root1] == self.rank[root2]:
                        self.rank[root2] += 1

    def dijkstra(graph, start, end):
        if start not in graph or end not in graph:
            return float("inf"), None

        n = len(graph)
        distance = [float('inf')] * n
        distance[start] = 0

        visited = set()
        q = [(0, start)]
        while q:
            curr_dist, curr_idx = heapq.heappop(q)
            if curr_idx in visited:
                continue
            visited.add(curr_idx)

            for nei, weight in graph[curr_idx]:
                if curr_dist + weight < distance[nei]:
                    distance[nei] = curr_dist + weight
                    heapq.heappush(q, (distance[nei], nei))

        return distance[end], [x for x in visited if x in distance and x != start]

    dsu = DSU(graph)
    unconnected = dsu.find(graph.index(target))

    # If source and target are in different connected components, they are unreachable
    if unconnected != dsu.find(graph.index(source)):
        return float("inf"), None

    # If the target is connected to source directly, the shortest path is just the target
    if target in graph[dsu.find(graph.index(source))]:
        return (0, [target])

    # If no path is found, we might have an unreachable situation, but a more thorough Dijkstra search should reveal it
    return dijkstra(graph, dsu.find(graph.index(source)), unconnected)
